             #{employeeId}, #{startDate}, #{endDate}, #{leaveType}, #{leaveStatus}, #{usedDays}, #{reason}
         )

mapper.update:
UPDATE leave_request
SET leave_status = #{leaveStatus},
    reject_reason = #{rejectReason}
WHERE leave_request_id = #{leaveRequestId}
  AND leave_status = 'PENDING'

mapper.select:
SELECT leave_request_id as leaveRequestId, employee_id as employeeId, start_date as startDate, end_date as endDate, leave_type as leaveType, leave_status as leaveStatus, used_days as usedDays, reason as reason, reject_reason as rejectReason FROM leave_request
leave_status = #{leaveStatus}
ORDER BY start_date DESC
